# Host-only actual-function boundaries; no device or timing model.
EXTENSION = '\nstruct mlx5e_dev{struct mlx5e_priv*priv;};\nstruct auxiliary_device{struct mlx5e_dev*driver_data;};\nstatic int resources_destroyed,device_present=1;\nstatic struct mlx5e_dev*auxiliary_get_drvdata(struct auxiliary_device*a){return a->driver_data;}\nstatic bool netif_device_present(struct net_device*n){(void)n;return device_present;}\n#define mlx5_sd_for_each_dev(i,m,pos) for((i)=0,(pos)=(m);(i)<1;(i)++)\nstatic void mlx5e_destroy_mdev_resources(struct mlx5_core_dev*m){(void)m;resources_destroyed++;}\n'
MAIN = '\nint main(int argc,char**argv){\n struct net_device n={};struct mlx5_core_dev m={};const struct mlx5e_profile profile={disable,rx,tx,cleanup};\n struct mlx5e_priv p={.profile=&profile,.netdev=&n,.mdev=&m};struct mlx5e_dev d={.priv=&p};struct auxiliary_device a={.driver_data=&d};\n int mode=atoi(argv[1]);inject_unknown=mode==1;p.peer_quarantined=mode>=2;\n if(mode==2){device_present=0;p.state=1UL<<MLX5E_STATE_DESTROYING;}\n int ret=_mlx5e_suspend(&a,false);\n if(!mode)return ret||resources_destroyed!=1||rx_cleanup!=1||tx_cleanup!=1;\n return ret!=-EIO||resources_destroyed||rx_cleanup||tx_cleanup||(!p.peer_quarantined);\n}\n'
